"""
strategy_coach_models.py — Data Models for AI Strategy Coach

Defines output dataclasses representing the AI Strategy Coach's analytical summary
and behavioral feedback.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List


@dataclass
class StrategyCoachResponse:
    """Comprehensive output generated by the AI Strategy Coach.

    Attributes:
        executive_summary: High-level natural-language summary of strategy evaluation.
        strengths: Key operational and statistical strengths.
        weaknesses: Identified risks, bottlenecks, or weak parameters.
        risk_observations: Specific risk management and drawdown observations.
        validation_summary: Explanation of strategy structure and validation status.
        backtest_interpretation: Plain-English interpretation of historical backtest.
        health_interpretation: Operational health score and state explanation.
        drift_interpretation: Assessment of statistical/behavioral drift vs baseline.
        behavior_summary: Overview of operational execution patterns.
        next_operational_steps: Non-investment operational recommendations.
        generation_method: Generation mechanism used ('llm' or 'deterministic_fallback').
        timestamp: ISO timestamp of analysis generation.
    """
    executive_summary: str = ""
    strengths: List[str] = field(default_factory=list)
    weaknesses: List[str] = field(default_factory=list)
    risk_observations: List[str] = field(default_factory=list)
    validation_summary: str = ""
    backtest_interpretation: str = ""
    health_interpretation: str = ""
    drift_interpretation: str = ""
    behavior_summary: str = ""
    next_operational_steps: List[str] = field(default_factory=list)
    generation_method: str = "deterministic_fallback"
    timestamp: str = ""

    def to_dict(self) -> Dict[str, Any]:
        """Convert response to clean dictionary."""
        return {
            "executive_summary": self.executive_summary,
            "strengths": self.strengths,
            "weaknesses": self.weaknesses,
            "risk_observations": self.risk_observations,
            "validation_summary": self.validation_summary,
            "backtest_interpretation": self.backtest_interpretation,
            "health_interpretation": self.health_interpretation,
            "drift_interpretation": self.drift_interpretation,
            "behavior_summary": self.behavior_summary,
            "next_operational_steps": self.next_operational_steps,
            "generation_method": self.generation_method,
            "timestamp": self.timestamp,
        }
